package net.civeira.phylax.feature.identity.user.application.usecase.create;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.identity.user.domain.UserApprovalStatusOptions;
import net.civeira.phylax.feature.identity.user.domain.UserChangeSet;

class UserCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the user input values are kept when converted to a change set and back")
  void test_user_create_input_change_set_round_trip() {
    UserCreateInput input = UserCreateInput.builder().uid("one").tenant(TenantReference.of("one"))
        .name("one").email("one")
        .welcomeAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .emailVerified(true).enabled(true).approvalStatus(UserApprovalStatusOptions.UNVERIFIED)
        .temporalPassword(true).useSecondFactors(true).blockedUntil(LocalDateTime
            .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .federatedProvider("one").version(1).build();
    UserChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    UserCreateInput copy = UserCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getTenant().isPresent(), "tenant must be assigned by the builder");
    Assertions.assertEquals(input.getTenant(), copy.getTenant(),
        "tenant must survive the change set round trip");
    Assertions.assertTrue(input.getName().isPresent(), "name must be assigned by the builder");
    Assertions.assertEquals(input.getName(), copy.getName(),
        "name must survive the change set round trip");
    Assertions.assertTrue(input.getEmail().isPresent(), "email must be assigned by the builder");
    Assertions.assertEquals(input.getEmail(), copy.getEmail(),
        "email must survive the change set round trip");
    Assertions.assertTrue(input.getWelcomeAt().isPresent(),
        "welcomeAt must be assigned by the builder");
    Assertions.assertEquals(input.getWelcomeAt(), copy.getWelcomeAt(),
        "welcomeAt must survive the change set round trip");
    Assertions.assertTrue(input.getEmailVerified().isPresent(),
        "emailVerified must be assigned by the builder");
    Assertions.assertEquals(input.getEmailVerified(), copy.getEmailVerified(),
        "emailVerified must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getApprovalStatus().isPresent(),
        "approvalStatus must be assigned by the builder");
    Assertions.assertEquals(input.getApprovalStatus(), copy.getApprovalStatus(),
        "approvalStatus must survive the change set round trip");
    Assertions.assertTrue(input.getTemporalPassword().isPresent(),
        "temporalPassword must be assigned by the builder");
    Assertions.assertEquals(input.getTemporalPassword(), copy.getTemporalPassword(),
        "temporalPassword must survive the change set round trip");
    Assertions.assertTrue(input.getUseSecondFactors().isPresent(),
        "useSecondFactors must be assigned by the builder");
    Assertions.assertEquals(input.getUseSecondFactors(), copy.getUseSecondFactors(),
        "useSecondFactors must survive the change set round trip");
    Assertions.assertTrue(input.getBlockedUntil().isPresent(),
        "blockedUntil must be assigned by the builder");
    Assertions.assertEquals(input.getBlockedUntil(), copy.getBlockedUntil(),
        "blockedUntil must survive the change set round trip");
    Assertions.assertTrue(input.getFederatedProvider().isPresent(),
        "federatedProvider must be assigned by the builder");
    Assertions.assertEquals(input.getFederatedProvider(), copy.getFederatedProvider(),
        "federatedProvider must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the user input builder can generate a new identifier")
  void test_user_create_input_new_uid() {
    UserCreateInput input = UserCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(), UserCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the user input starts empty and the setters assign values")
  void test_user_create_input_setters() {
    UserCreateInput empty = UserCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getTenant().isEmpty(), "tenant must be empty by default");
    Assertions.assertSame(empty, empty.setTenant(TenantReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTenant().isPresent(), "tenant must be assigned by the setter");
    Assertions.assertTrue(empty.getName().isEmpty(), "name must be empty by default");
    Assertions.assertSame(empty, empty.setName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getName().isPresent(), "name must be assigned by the setter");
    Assertions.assertTrue(empty.getEmail().isEmpty(), "email must be empty by default");
    Assertions.assertSame(empty, empty.setEmail("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEmail().isPresent(), "email must be assigned by the setter");
    Assertions.assertTrue(empty.getWelcomeAt().isEmpty(), "welcomeAt must be empty by default");
    Assertions.assertSame(
        empty, empty.setWelcomeAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getWelcomeAt().isPresent(),
        "welcomeAt must be assigned by the setter");
    Assertions.assertTrue(empty.getEmailVerified().isEmpty(),
        "emailVerified must be empty by default");
    Assertions.assertSame(empty, empty.setEmailVerified(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEmailVerified().isPresent(),
        "emailVerified must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getApprovalStatus().isEmpty(),
        "approvalStatus must be empty by default");
    Assertions.assertSame(empty, empty.setApprovalStatus(UserApprovalStatusOptions.UNVERIFIED),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getApprovalStatus().isPresent(),
        "approvalStatus must be assigned by the setter");
    Assertions.assertTrue(empty.getTemporalPassword().isEmpty(),
        "temporalPassword must be empty by default");
    Assertions.assertSame(empty, empty.setTemporalPassword(true),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getTemporalPassword().isPresent(),
        "temporalPassword must be assigned by the setter");
    Assertions.assertTrue(empty.getUseSecondFactors().isEmpty(),
        "useSecondFactors must be empty by default");
    Assertions.assertSame(empty, empty.setUseSecondFactors(true),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUseSecondFactors().isPresent(),
        "useSecondFactors must be assigned by the setter");
    Assertions.assertTrue(empty.getBlockedUntil().isEmpty(),
        "blockedUntil must be empty by default");
    Assertions.assertSame(
        empty, empty.setBlockedUntil(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getBlockedUntil().isPresent(),
        "blockedUntil must be assigned by the setter");
    Assertions.assertTrue(empty.getFederatedProvider().isEmpty(),
        "federatedProvider must be empty by default");
    Assertions.assertSame(empty, empty.setFederatedProvider("one"),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getFederatedProvider().isPresent(),
        "federatedProvider must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
